# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
package db.migration;

import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;
import org.flywaydb.core.api.migration.BaseJavaMigration;
import org.flywaydb.core.api.migration.Context;

/**
 * A claim's amount may be negative: a correction. Drops the unnamed check on claim.amount (amount >= 0)
 * from V5, looking up the name the database gave it.
 */
public class V24__claim_amount_signed extends BaseJavaMigration {

    @Override
    public void migrate(Context context) throws Exception {
        List<String> names = new ArrayList<>();
        try (PreparedStatement query = context.getConnection().prepareStatement(
                "SELECT cc.CONSTRAINT_NAME FROM INFORMATION_SCHEMA.CHECK_CONSTRAINTS cc"
                        + " JOIN INFORMATION_SCHEMA.TABLE_CONSTRAINTS tc"
                        + " ON tc.CONSTRAINT_SCHEMA = cc.CONSTRAINT_SCHEMA AND tc.CONSTRAINT_NAME = cc.CONSTRAINT_NAME"
                        + " WHERE tc.TABLE_NAME = 'CLAIM' AND UPPER(cc.CHECK_CLAUSE) LIKE '%AMOUNT%'");
                ResultSet rows = query.executeQuery()) {
            while (rows.next()) names.add(rows.getString(1));
        }
        try (Statement drop = context.getConnection().createStatement()) {
            for (String name : names) drop.execute("ALTER TABLE claim DROP CONSTRAINT \"" + name + "\"");
        }
    }
}
-- The sheet's period numbering from: while set and the sheet's today is on or after it, a claim
-- opened is numbered within its period (<period name>-<n>), or X-<n> when in no period. Empty: off.
ALTER TABLE sheet ADD COLUMN period_numbering_from DATE;
-- A claim's number is now text: the sheet-wide number (1, 2, ...) or a number within a period.
-- A correction names the number of the claim it corrects in the same form.
DROP INDEX claim_sheet_number;
ALTER TABLE claim ALTER COLUMN claim_number VARCHAR(220);
ALTER TABLE claim ALTER COLUMN corrects VARCHAR(220);
-- A claim numbered within a period: the period's name (empty: in no period) and its place in it.
ALTER TABLE claim ADD COLUMN number_period VARCHAR(200);
ALTER TABLE claim ADD COLUMN number_seq INT;

